import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';

export const interval = 5000;
export const maxPollingSteps = 5;

/** Poll while a newly created backend object is becoming available in events. */
export const usePollEvents = () => {
    const eventManager = useEventManager();

    return (property?: string, action?: EVENT_ACTIONS): Promise<void> =>
        new Promise((resolve, reject) => {
            let finished = false;
            let attempts = 0;
            let timer: ReturnType<typeof setTimeout> | undefined;
            let unsubscribe: (() => void) | undefined;

            const finish = (error?: unknown) => {
                if (finished) {
                    return;
                }
                finished = true;
                if (timer !== undefined) {
                    clearTimeout(timer);
                }
                unsubscribe?.();
                if (error !== undefined) {
                    reject(error);
                } else {
                    resolve();
                }
            };

            const poll = async () => {
                if (finished) {
                    return;
                }
                attempts += 1;
                try {
                    await eventManager.call();
                } catch (error) {
                    finish(error);
                    return;
                }
                if (finished) {
                    return;
                }
                if (attempts === maxPollingSteps) {
                    finish();
                } else {
                    timer = setTimeout(poll, interval);
                }
            };

            if (property && action !== undefined) {
                unsubscribe = eventManager.subscribe((event) => {
                    if (finished) {
                        return;
                    }
                    const updates = (event as unknown as Record<string, { Action: EVENT_ACTIONS }[] | undefined>)[
                        property
                    ];
                    if (updates?.some((update) => update.Action === action)) {
                        finish();
                    }
                });
                // A synchronous subscription callback can finish before subscribe returns.
                if (finished) {
                    unsubscribe();
                    return;
                }
            }

            timer = setTimeout(poll, interval);
        });
};
import { act, renderHook } from '@testing-library/react';

import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';
import { interval, maxPollingSteps, usePollEvents } from './usePollEvents';

jest.mock('../../hooks', () => ({ useEventManager: jest.fn() }));

describe('usePollEvents', () => {
    const call = jest.fn<Promise<void>, []>();
    const unsubscribe = jest.fn();
    let handler: (event: any) => void;
    const subscribe = jest.fn((callback: typeof handler) => {
        handler = callback;
        return unsubscribe;
    });

    beforeEach(() => {
        jest.useFakeTimers();
        jest.clearAllMocks();
        call.mockResolvedValue(undefined);
        jest.mocked(useEventManager).mockReturnValue({ call, subscribe } as any);
    });

    afterEach(() => jest.useRealTimers());

    it('calls at five second intervals and stops after five attempts', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current();

        for (let step = 1; step <= maxPollingSteps; step += 1) {
            await act(async () => {
                await jest.advanceTimersByTimeAsync(interval - 1);
            });
            expect(call).toHaveBeenCalledTimes(step - 1);
            await act(async () => {
                await jest.advanceTimersByTimeAsync(1);
            });
            expect(call).toHaveBeenCalledTimes(step);
        }

        await done;
        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval * 2);
        });
        expect(call).toHaveBeenCalledTimes(maxPollingSteps);
        expect(subscribe).not.toHaveBeenCalled();
    });

    it('ignores unrelated events, stops on a match, and ignores late callbacks', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);

        handler({ Subscriptions: [{ Action: EVENT_ACTIONS.CREATE }] });
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.UPDATE }] });
        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval);
        });
        expect(call).toHaveBeenCalledTimes(1);

        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        await done;
        expect(unsubscribe).toHaveBeenCalledTimes(1);
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
        });
        expect(call).toHaveBeenCalledTimes(1);
        expect(unsubscribe).toHaveBeenCalledTimes(1);
    });

    it('unsubscribes after exhausting attempts without a matching event', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);

        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
        });
        await done;
        expect(call).toHaveBeenCalledTimes(maxPollingSteps);
        expect(unsubscribe).toHaveBeenCalledTimes(1);
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        expect(unsubscribe).toHaveBeenCalledTimes(1);
    });

    it('does not schedule another call when a matching event arrives during a call', async () => {
        let resolveCall: () => void = () => {};
        call.mockImplementation(() => new Promise<void>((resolve) => { resolveCall = resolve; }));
        const { result } = renderHook(() => usePollEvents());
        const done = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);

        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval);
        });
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        resolveCall();
        await done;
        await act(async () => {
            await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
        });
        expect(call).toHaveBeenCalledTimes(1);
        expect(unsubscribe).toHaveBeenCalledTimes(1);
    });
});

    const paymentMethodType = PAYMENT_METHOD_TYPES.PAYPAL;

    useEffect(() => {
        const run = async () => {
            const result = await api<PaymentTokenResult>(
                createTokenV4({
                    Amount: PAYMENT_AUTHORIZATION_AMOUNT,
                    Currency: PAYMENT_AUTHORIZATION_CURRENCY,
                    Payment: {
                        Type: paymentMethodType,
                    },
                })
            );
            paypalRef.current = result;
        };
        void withLoadingToken(run());
        return () => {
            abortRef.current?.abort();
        };
    }, []);

    const handleSubmit = async (data: PaymentTokenResult) => {
        try {
            abortRef.current = new AbortController();
            await ensureTokenChargeable({
                Token: data.Token,
                api,
                ApprovalURL: data.ApprovalURL,
                ReturnHost: data.ReturnHost,
                signal: abortRef.current.signal,
            });
            await api(
                setPaymentMethodV4({
                    Type: PAYMENT_METHOD_TYPES.TOKEN,
                    Details: {
                        Token: data.Token,
                    },
                })
            );
            await call();
            onClose?.();
            createNotification({ text: c('Success').t`Payment method added` });
        } catch (error: any) {
            // if not coming from API error
            if (error && error.message && !error.config) {
                createNotification({ text: error.message, type: 'error' });
            }
        }
    };

    return (
        <Prompt
            data-testid="addPPalModalTitle"
            title={c('Title').t`Add PayPal payment method`}
            onClose={onClose}
            buttons={[
                <Button
                    color="norm"
                    loading={loading}
                    disabled={loadingToken}
                    onClick={() => {
                        if (!paypalRef.current) {
                            return;
                        }
                        void withLoading(handleSubmit(paypalRef.current));
                    }}
                >{c('Action').t`Add PayPal`}</Button>,
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            {loading ? (
                <>
                    <div className="mb-4">{c('Info').t`Please verify payment at the new tab which was opened.`}</div>
                    <div>{c('Info').t`Verification can take a few minutes.`}</div>
                </>
            ) : (
                <>
                    <div className="mb-4">
                        {c('Info')
                            .t`This will enable PayPal to be used to pay for your ${BRAND_NAME} subscription. We will redirect you to PayPal in a new browser tab. If you use any pop-up blockers, please disable them to continue.`}
